-- =============================================================================
-- Corlix Hub · Colunas identity durante a carga dos CSVs do backup
-- Guia: modulos/ambientes/Etapas-ambientes.md (3.2)
--
-- Uso, conectado como dono do schema de destino (DEV ou UAT, nunca PRD):
--   @modulos/ambientes/identidades.sql ANTES    -- antes do "load table"
--   @modulos/ambientes/identidades.sql DEPOIS   -- depois de carregar tudo
--
-- ANTES:  colunas GENERATED ALWAYS não aceitam valor no insert. Elas passam a
--         GENERATED BY DEFAULT, e o nome fica anotado na tabela AMB_IDENTIDADE.
-- DEPOIS: toda coluna identity recomeça depois do maior valor carregado
--         (START WITH LIMIT VALUE). As anotadas voltam a GENERATED ALWAYS e a
--         tabela AMB_IDENTIDADE é apagada.
-- =============================================================================
whenever sqlerror exit failure rollback
set serveroutput on size unlimited
set verify off
define fase = '&1'

declare
  l_fase varchar2(10) := upper('&fase');
  l_qt   pls_integer;
  l_tipo varchar2(30);
begin
  if l_fase not in ('ANTES', 'DEPOIS') then
    raise_application_error(-20000, 'Use ANTES ou DEPOIS.');
  end if;

  select count(*) into l_qt from user_tables where table_name = 'AMB_IDENTIDADE';

  if l_fase = 'ANTES' then
    if l_qt = 0 then
      execute immediate 'create table amb_identidade (nm_tabela varchar2(128), nm_coluna varchar2(128))';
    end if;
    for c in (select table_name, column_name
                from user_tab_identity_cols
               where generation_type = 'ALWAYS') loop
      execute immediate 'insert into amb_identidade values (:1, :2)' using c.table_name, c.column_name;
      execute immediate 'alter table "' || c.table_name || '" modify "' || c.column_name
                     || '" generated by default as identity';
      dbms_output.put_line('BY DEFAULT: ' || c.table_name || '.' || c.column_name);
    end loop;
    commit;
  else
    for c in (select i.table_name, i.column_name,
                     case when i.generation_type = 'BY DEFAULT' and t.default_on_null = 'YES'
                          then 'BY DEFAULT ON NULL' else i.generation_type end as generation_type
                from user_tab_identity_cols i
                join user_tab_columns t
                  on t.table_name = i.table_name and t.column_name = i.column_name
               where i.table_name <> 'AMB_IDENTIDADE') loop
      l_tipo := c.generation_type;
      if l_qt > 0 then
        execute immediate 'select count(*) from amb_identidade where nm_tabela = :1 and nm_coluna = :2'
          into l_qt using c.table_name, c.column_name;
        if l_qt > 0 then
          l_tipo := 'ALWAYS';
        end if;
        l_qt := 1;  -- a tabela existe; segue consultando nas próximas colunas
      end if;
      execute immediate 'alter table "' || c.table_name || '" modify "' || c.column_name
                     || '" generated ' || case l_tipo
                                            when 'ALWAYS' then 'always'
                                            when 'BY DEFAULT ON NULL' then 'by default on null'
                                            else 'by default'
                                          end
                     || ' as identity (start with limit value)';
      dbms_output.put_line(l_tipo || ', recomeça depois do maior valor: ' || c.table_name || '.' || c.column_name);
    end loop;
    select count(*) into l_qt from user_tables where table_name = 'AMB_IDENTIDADE';
    if l_qt > 0 then
      execute immediate 'drop table amb_identidade purge';
    end if;
  end if;
end;
/
